class NegativeAmount(Exception):
    pass

def check(amount):
    if amount < 0:
        raise NegativeAmount("amount must be >= 0")
    return amount

for value in [5, -3]:
    try:
        print(check(value))
    except NegativeAmount as error:
        print("Error:", error)

