orders = [
    {"customer": "Ana", "qty": 2},
    {"customer": "", "qty": 1},
    {"customer": "Bo", "qty": 0},
    {"qty": 4},
    {"customer": "Cy", "qty": 7},
]

def validate(order):
    if not order.get("customer"):
        raise ValueError("missing customer")
    qty = order.get("qty")
    if not isinstance(qty, int) or qty <= 0:
        raise ValueError("bad qty")

valid = 0
for order in orders:
    try:
        validate(order)
    except ValueError as error:
        print("rejected:", error)
    else:
        valid += 1
        print("ok:", order["customer"])
print(f"Valid {valid} of {len(orders)}")

import logging
import sys

calls = 0

def reset():
    global calls
    calls = 0

def flaky():
    global calls
    calls += 1
    if calls < 3:
        raise ConnectionError("down")
    return "data"

logger = logging.getLogger("retry")
logger.handlers.clear()   # drop handlers left by an earlier run
logger.setLevel(logging.INFO)
logger.propagate = False
handler = logging.StreamHandler(sys.stdout)
handler.setFormatter(logging.Formatter("%(levelname)s %(message)s"))
logger.addHandler(handler)

def fetch_with_retry(max_attempts):
    for attempt in range(1, max_attempts + 1):
        try:
            return flaky()
        except ConnectionError:
            logger.warning("attempt %d failed", attempt)
    raise RuntimeError("gave up")

print(fetch_with_retry(3))
reset()
try:
    fetch_with_retry(2)
except RuntimeError as error:
    print(error)

def process(values):
    print("start")
    try:
        return sum(float(v) for v in values)
    finally:
        print("end")

print(process(["1", "2.5"]))
try:
    process(["1", "x"])
except ValueError as error:
    print("failed:", error)

